  "implementation": "def solve(case):
    import json

    # Validate required fields
    if 'min_cluster_size' not in case or not isinstance(case['min_cluster_size'], int):
        raise ValueError('min_cluster_size must be an integer')
    if 'clusters' not in case or not isinstance(case['clusters'], list):
        raise ValueError('clusters must be a list')
    if 'parent' not in case or not isinstance(case['parent'], dict):
        raise ValueError('parent must be a dict')

    min_size = case['min_cluster_size']
    cluster_list = case['clusters']
    parent_map = case['parent']

    # Build cluster lookup
    clusters = {}
    for c in cluster_list:
        if 'cluster_id' not in c or 'size' not in c or 'birth_lambda' not in c or 'point_exit_lambdas' not in c:
            raise ValueError('Each cluster must have cluster_id, size, birth_lambda, point_exit_lambdas')
        if not isinstance(c['cluster_id'], str) or not isinstance(c['size'], int) or not isinstance(c['birth_lambda'], (int, float)) or not isinstance(c['point_exit_lambdas'], list):
            raise ValueError('Invalid cluster field types')
        for lam in c['point_exit_lambdas']:
            if not isinstance(lam, (int, float)):
                raise ValueError('point_exit_lambdas must contain numbers')
        clusters[c['cluster_id']] = c

    # Build children mapping
    children = {}
    for cid in clusters:
        children[cid] = []
    for cid, pid in parent_map.items():
        if cid not in clusters:
            raise ValueError(f'Parent map contains unknown cluster {cid}')
        if pid is not None:
            if pid not in clusters:
                raise ValueError(f'Parent {pid} not in clusters')
            children[pid].append(cid)

    # Find roots
    roots = [cid for cid in clusters if parent_map.get(cid) is None]
    if not roots:
        raise ValueError('No root cluster (cluster with parent null)')

    # Condensation: remove clusters smaller than min_size and adjust parent links
    retained = set()
    condensed_parent = {}  # cluster_id -> parent_id (only among retained)

    def condense(node_id, current_parent):
        node = clusters[node_id]
        if node['size'] < min_size:
            # skip this node, pass children to current_parent
            for child_id in children.get(node_id, []):
                condense(child_id, current_parent)
        else:
            retained.add(node_id)
            condensed_parent[node_id] = current_parent
            for child_id in children.get(node_id, []):
                condense(child_id, node_id)

    for root in roots:
        condense(root, None)

    # Build output clusters with stability
    out_clusters = []
    for cid in retained:
        c = clusters[cid]
        birth = c['birth_lambda']
        stability = sum(max(0.0, exit - birth) for exit in c['point_exit_lambdas'])
        out_clusters.append({
            'cluster_id': cid,
            'size': c['size'],
            'stability': stability
        })

    # Selection: by decreasing stability, then cluster_id ascending
    candidates = sorted(out_clusters, key=lambda x: (-x['stability'], x['cluster_id']))

    blocked = set()
    selected = []
    for cand in candidates:
        cid = cand['cluster_id']
        if cid in blocked:
            continue
        selected.append(cid)
        # block all ancestors
        cur = condensed_parent.get(cid)
        while cur is not None:
            blocked.add(cur)
            cur = condensed_parent.get(cur)

    # Sort selected ids alphabetically
    selected_sorted = sorted(selected)

    return {
        'clusters': out_clusters,
        'selected_cluster_ids': selected_sorted
    }"
}
